_SIGNATURE = "bool block_frame(const uint8_t *f, size_t n)"

# Compact test harness Devin recreates and runs in its VM. Reads two hex-frame
# files (one frame per line) and prints the detection / false-positive rates.
HARNESS_C = r"""#include <ctype.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include "filter.c"

static int parse_hex(const char *line, uint8_t *out, int cap) {
    int n = 0, hi = -1;
    for (const char *p = line; *p; ++p) {
        char c = *p; int v;
        if (c == '#') break;
        if (isspace((unsigned char)c) || c=='_' || c==':' || c=='-') continue;
        if (c>='0'&&c<='9') v=c-'0';
        else if (c>='a'&&c<='f') v=c-'a'+10;
        else if (c>='A'&&c<='F') v=c-'A'+10;
        else return -1;
        if (hi<0) hi=v; else { if(n<cap) out[n++]=(uint8_t)((hi<<4)|v); hi=-1; }
    }
    return n?n:-1;
}
static void score(const char*path, bool expect, int*ok, int*tot){
    FILE*f=fopen(path,"r"); if(!f){perror(path);return;}
    char line[8192]; uint8_t fr[4096];
    while(fgets(line,sizeof line,f)){int len=parse_hex(line,fr,sizeof fr);
        if(len<0)continue; (*tot)++; if(block_frame(fr,(size_t)len)==expect)(*ok)++;}
    fclose(f);
}
int main(int argc,char**argv){ if(argc<3){fprintf(stderr,"usage: %s attack benign\n",argv[0]);return 2;}
