    double tpr=at?(double)tp/at:0, fpr=bt?(double)(bt-tn)/bt:0;
    printf("TPR=%.3f FPR=%.3f\n",tpr,fpr);
    return (tp==at && tn==bt && at>0)?0:1;
}
